<script setup lang="ts">
import{reactive,ref}from'vue';import{Head,Link,router}from'@inertiajs/vue3';import{route}from'ziggy-js';interface Categoria{id:string;nombre:string;descripcion?:string;estado:string}interface Proveedor{id:string;documento:string;nombre:string;contacto?:string;telefono?:string;email?:string;estado:string}const props=defineProps<{categorias:Categoria[];proveedores:Proveedor[]}>();const procesando=ref(false);const categoria=reactive({id:'',nombre:'',descripcion:''});const proveedor=reactive({id:'',documento:'',nombre:'',contacto:'',telefono:'',email:''});function editarCategoria(c:Categoria){Object.assign(categoria,{id:c.id,nombre:c.nombre,descripcion:c.descripcion||''})}function editarProveedor(p:Proveedor){Object.assign(proveedor,{id:p.id,documento:p.documento,nombre:p.nombre,contacto:p.contacto||'',telefono:p.telefono||'',email:p.email||''})}function guardarCategoria(){procesando.value=true;const reset=()=>Object.assign(categoria,{id:'',nombre:'',descripcion:''});const opciones={preserveScroll:true,onSuccess:reset,onFinish:()=>procesando.value=false};categoria.id?router.put(route('inventario.categorias.update',categoria.id),categoria,opciones):router.post(route('inventario.categorias.store'),categoria,opciones)}function guardarProveedor(){procesando.value=true;const reset=()=>Object.assign(proveedor,{id:'',documento:'',nombre:'',contacto:'',telefono:'',email:''});const opciones={preserveScroll:true,onSuccess:reset,onFinish:()=>procesando.value=false};proveedor.id?router.put(route('inventario.proveedores.update',proveedor.id),proveedor,opciones):router.post(route('inventario.proveedores.store'),proveedor,opciones)}function estado(tipo:'categorias'|'proveedores',item:Categoria|Proveedor,nuevo:string){if(!confirm(`¿Cambiar ${item.nombre} a ${nuevo}?`))return;router.patch(route(`inventario.${tipo}.estado`,item.id),{estado:nuevo},{preserveScroll:true})}
</script>
<template><Head title="Catálogos de inventario"/><UDashboardPanel><template #header><UDashboardNavbar title="Categorías y proveedores"><template #leading><UDashboardSidebarCollapse/></template><template #right><Link :href="route('inventario.index')"><UButton color="neutral" variant="outline" label="Volver al inventario"/></Link></template></UDashboardNavbar></template><template #body><div class="grid gap-8 xl:grid-cols-2"><section class="space-y-4"><UCard><template #header><h2 class="font-semibold">{{categoria.id?'Editar categoría':'Nueva categoría'}}</h2></template><form class="space-y-4" @submit.prevent="guardarCategoria"><UFormField label="Nombre" required><UInput v-model="categoria.nombre" class="w-full"/></UFormField><UFormField label="Descripción"><UTextarea v-model="categoria.descripcion" class="w-full"/></UFormField><div class="flex justify-end gap-2"><UButton v-if="categoria.id" color="neutral" variant="ghost" label="Cancelar" @click="Object.assign(categoria,{id:'',nombre:'',descripcion:''})"/><UButton type="submit" :label="categoria.id?'Guardar cambios':'Crear categoría'" :loading="procesando"/></div></form></UCard><h2 class="text-lg font-semibold">Categorías</h2><UCard v-for="c in categorias" :key="c.id"><div class="flex items-start justify-between gap-3"><div><p class="font-medium">{{c.nombre}}</p><p class="text-sm text-muted">{{c.descripcion||'Sin descripción'}}</p></div><UBadge :color="c.estado==='activo'?'success':'neutral'">{{c.estado}}</UBadge></div><template #footer><div class="flex flex-wrap justify-end gap-1"><UButton size="xs" color="neutral" variant="ghost" label="Editar" @click="editarCategoria(c)"/><UButton size="xs" color="neutral" variant="ghost" :label="c.estado==='activo'?'Desactivar':'Activar'" @click="estado('categorias',c,c.estado==='activo'?'inactivo':'activo')"/><UButton v-if="c.estado!=='archivado'" size="xs" color="error" variant="ghost" label="Archivar" @click="estado('categorias',c,'archivado')"/></div></template></UCard></section><section class="space-y-4"><UCard><template #header><h2 class="font-semibold">{{proveedor.id?'Editar proveedor':'Nuevo proveedor'}}</h2></template><form class="grid gap-4 sm:grid-cols-2" @submit.prevent="guardarProveedor"><UFormField label="Documento" required><UInput v-model="proveedor.documento" class="w-full"/></UFormField><UFormField label="Nombre" required><UInput v-model="proveedor.nombre" class="w-full"/></UFormField><UFormField label="Contacto"><UInput v-model="proveedor.contacto" class="w-full"/></UFormField><UFormField label="Teléfono"><UInput v-model="proveedor.telefono" class="w-full"/></UFormField><UFormField label="Correo"><UInput v-model="proveedor.email" type="email" class="w-full"/></UFormField><div class="self-end text-right"><UButton v-if="proveedor.id" color="neutral" variant="ghost" label="Cancelar" @click="Object.assign(proveedor,{id:'',documento:'',nombre:'',contacto:'',telefono:'',email:''})"/><UButton type="submit" :label="proveedor.id?'Guardar':'Crear proveedor'" :loading="procesando"/></div></form></UCard><h2 class="text-lg font-semibold">Proveedores</h2><UCard v-for="p in proveedores" :key="p.id"><div class="flex items-start justify-between gap-3"><div><p class="font-medium">{{p.nombre}} · {{p.documento}}</p><p class="text-sm text-muted">{{p.contacto||'Sin contacto'}} · {{p.telefono||'Sin teléfono'}}</p><p v-if="p.email" class="text-sm text-muted">{{p.email}}</p></div><UBadge :color="p.estado==='activo'?'success':'neutral'">{{p.estado}}</UBadge></div><template #footer><div class="flex flex-wrap justify-end gap-1"><UButton size="xs" color="neutral" variant="ghost" label="Editar" @click="editarProveedor(p)"/><UButton size="xs" color="neutral" variant="ghost" :label="p.estado==='activo'?'Desactivar':'Activar'" @click="estado('proveedores',p,p.estado==='activo'?'inactivo':'activo')"/><UButton v-if="p.estado!=='archivado'" size="xs" color="error" variant="ghost" label="Archivar" @click="estado('proveedores',p,'archivado')"/></div></template></UCard></section></div></template></UDashboardPanel></template>
